#!/bin/bash
# ==============================================================================
# regen.sh -- regenerate every generated file of the Genesys 2 fabric benchmark
# ==============================================================================
# One input, every leg: rtl/bridges/configs/bridge_fb_data.toml (+ connectivity)
#   1. bridge generator  -> rtl/bridges/generated/bridge_fb_data/  (Leg A fabric)
#                           rtl/bridges/generated/bridge_fb_data_plain/ (Leg A2:
#                             the same TOML with preset = "xbar", derived into
#                             rtl/bridges/generated/derived/ -- never a second
#                             hand-kept config)
#                           rtl/bridges/generated/bridge_fb_cfg/   (config bridge)
#                           rtl/bridges/filelists/bridge_fb_data{,_plain}.f
#   2. gen_fabric_legs   -> rtl/generated/fb_data_fabric_bridge/   (Leg A wrapper)
#                           rtl/generated/fb_data_fabric_bridge_plain/ (Leg A2 wrapper)
#                           rtl/generated/fb_data_fabric_xbar/     (Leg B1 wrapper)
#                           rtl/generated/fb_data_fabric_sc/       (Leg B2 wrapper)
#                           rtl/generated/fb_data_fabric_{forencich,pulp,litex}/
#                                                      (Legs C1, C2, C3 wrappers)
#                           rtl/generated/fb_vendor_ip_cfg/        (Vivado IP + BD config)
#   3. gen_litex_xbar.py -> rtl/generated/fb_litex_xbar/          (Leg C3 crossbar, LiteX;
#                           tracked, needs the LiteX venv to change)
#   4. gen_litedram.sh   -> rtl/generated/fb_litedram/             (S0 LiteDRAM DDR3 core;
#                           skipped while current for its config)
# The Vivado IP itself (fpga/ip/build) is regenerated by `make vendor-ip`.
# The steps always run together: a TOML change that reached only one leg is a
# topology mismatch between the legs, which is the one thing the benchmark
# cannot tolerate. RTL only -- this script writes no DV.
# ==============================================================================
set -euo pipefail
AREA="$(cd "$(dirname "${BASH_SOURCE[0]}")/.." && pwd)"
REPO_ROOT="${REPO_ROOT:-$(git -C "$AREA" rev-parse --show-toplevel)}"
CFG="$AREA/rtl/bridges/configs"

# Serialize: every build-<leg> runs this as its PREBUILD, and the bridge
# generator rmtree()s each output directory before rewriting it, so two builds
# regenerating at once delete each other's files mid-write (the STREAM area's
# regen_bridges.sh hit exactly this). Blocking: a second caller waits and then
# writes the same bytes. *.lock is gitignored.
if [ -z "${FB_REGEN_LOCKED:-}" ]; then
    exec env FB_REGEN_LOCKED=1 flock "$AREA/rtl/.regen.lock" bash "$0" "$@"
fi

echo "[regen] bridge_fb_data (Leg A fabric)"
python3 "$REPO_ROOT/projects/components/fabric-gen-ip/bridge/bin/bridge_generator.py" \
    --ports "$CFG/bridge_fb_data.toml" \
    --connectivity "$CFG/bridge_fb_data_connectivity.csv" \
    --name bridge_fb_data \
    --output-dir "$AREA/rtl/bridges/generated" > /dev/null
echo "[regen] bridge_fb_data_plain (Leg A2: Leg A's TOML + preset = \"xbar\")"
DERIVED="$AREA/rtl/bridges/generated/derived"
mkdir -p "$DERIVED"
python3 - "$CFG/bridge_fb_data.toml" "$DERIVED/bridge_fb_data_plain.toml" <<'PY'
import re, sys
src, dst = sys.argv[1:]
text = open(src).read()
head = ("# GENERATED by bin/regen.sh from rtl/bridges/configs/bridge_fb_data.toml\n"
        "# DO NOT EDIT: Leg A2 is Leg A with preset = \"xbar\" and nothing else.\n")
out, n = re.subn(r'(?m)^name = "bridge_fb_data"$',
                 'name = "bridge_fb_data_plain"\npreset = "xbar"', text, count=1)
if n != 1 or re.search(r'(?m)^preset\s*=', text):
    sys.exit("regen: bridge_fb_data.toml must have one [bridge] name line and no preset")
open(dst, "w").write(head + out)
PY
python3 "$REPO_ROOT/projects/components/fabric-gen-ip/bridge/bin/bridge_generator.py" \
    --ports "$DERIVED/bridge_fb_data_plain.toml" \
    --connectivity "$CFG/bridge_fb_data_connectivity.csv" \
    --name bridge_fb_data_plain \
    --output-dir "$AREA/rtl/bridges/generated" > /dev/null
echo "[regen] bridge_fb_cfg (host configuration bridge, held constant across legs)"
python3 "$REPO_ROOT/projects/components/fabric-gen-ip/bridge/bin/bridge_generator.py" \
    --ports "$CFG/bridge_fb_cfg.toml" \
    --connectivity "$CFG/bridge_fb_cfg_connectivity.csv" \
    --name bridge_fb_cfg \
    --output-dir "$AREA/rtl/bridges/generated" > /dev/null
echo "[regen] fb_data_fabric wrappers (every leg)"
python3 "$AREA/bin/gen_fabric_legs.py"
echo "[regen] fb_litex_xbar (Leg C3: LiteX AXI crossbar)"
# Tracked output, so the sim needs no LiteX. With the venv: regenerate (the
# output is deterministic). Without it: keep it only while its recorded input
# hash still matches -- a topology change must not leave C3 on the old one.
LITEX_PY="${LITEX_VENV:-/mnt/data/tools/litex-venv}/bin/python"
LITEX_V="$AREA/rtl/generated/fb_litex_xbar/fb_litex_xbar.v"
if [ -x "$LITEX_PY" ]; then
    "$LITEX_PY" "$AREA/bin/gen_litex_xbar.py"
else
    want="$(cat "$CFG/bridge_fb_data.toml" "$CFG/bridge_fb_data_connectivity.csv" \
                "$AREA/bin/gen_litex_xbar.py" "$AREA/bin/gen_fabric_legs.py" | sha256sum | cut -d' ' -f1)"
    have="$(sed -n 's|^// inputs-sha256: ||p' "$LITEX_V" 2>/dev/null || true)"
    if [ "$want" != "$have" ]; then
        echo "[regen] fb_litex_xbar is stale and there is no LiteX at $LITEX_PY: set LITEX_VENV"
        exit 1
    fi
    echo "[regen] fb_litex_xbar current (no LiteX venv; inputs unchanged)"
fi
echo "[regen] fb_litedram (S0 DDR3 controller)"
bash "$AREA/bin/gen_litedram.sh"
echo "[regen] done"
